      END_STATE();
    case 8:
      ACCEPT_TOKEN(sym_done_marker);
      END_STATE();
    case 9:
      ACCEPT_TOKEN(sym_fail_marker);
      END_STATE();
    case 10:
      ACCEPT_TOKEN(sym_info_marker);
      END_STATE();
    case 11:
      ACCEPT_TOKEN(aux_sym__spaces_token1);
      if (lookahead == '\t') ADVANCE(15);
      if (lookahead == '\n') ADVANCE(13);
      if (lookahead == '\r') ADVANCE(14);
      if (lookahead == ' ') ADVANCE(11);
      END_STATE();
    case 12:
      ACCEPT_TOKEN(aux_sym__spaces_token1);
      if (lookahead == ' ') ADVANCE(12);
      END_STATE();
    case 13:
